1	// src/lib/rechner/netzanschluss.js
2	//
3	// Netzanschluss-Check für Solarparks: grobe Kosten, Zeitrahmen, Risiken und
4	// Tipps je nach Größe, Entfernung, Spannungsebene, Netzkapazität, Überbauung
5	// und Speicher. Reine Funktionen ohne React:
6	//
7	//   node src/lib/rechner/netzanschluss.js      → Selbsttest
8	//
9	// Grundlagen (DE): § 8 EEG (Anschlusspflicht, Netzverknüpfungspunkt, Fristen),
10	// § 8a EEG (flexible Netzanschlussvereinbarung / Überbauung), § 16 EEG (Kosten
11	// des Anschlusses bis zum Verknüpfungspunkt trägt der Anlagenbetreiber),
12	// § 17 EEG (Kosten der Kapazitätserweiterung trägt der Netzbetreiber).
13	// Ein Baukostenzuschuss fällt für reine Einspeiser in der Regel nicht an –
14	// wohl aber für Netzbezug, etwa eines Speichers, der aus dem Netz lädt.
15	// Kostenbausteine: FREIFLAECHE (+ .netz), SPEICHER.bkzProKw (markt.js).
16	
17	import { ERLOESE, FREIFLAECHE, REGIONEN, SPEICHER, laenderSperre } from "../invest/markt.js";
18	
19	const N = FREIFLAECHE.netz;
20	
21	export const EBENEN = [
22	  { id: "auto", label: "Automatisch", sub: "nach Leistung" },
23	  { id: "msLeitung", label: "MS-Leitung", sub: "Einschleifen 20 kV" },
24	  { id: "uwMs", label: "Umspannwerk", sub: "MS-Sammelschiene" },
25	  { id: "hs", label: "110 kV", sub: "eigenes Umspannwerk" },
26	];
27	
28	export const KAPAZITAETEN = [
29	  { id: "frei", label: "Bekannt: frei", sub: "Auskunft liegt vor" },
30	  { id: "unbekannt", label: "Unbekannt", sub: "noch nicht angefragt" },
31	  { id: "knapp", label: "Bekannt: knapp", sub: "Ausbau nötig" },
32	];
33	
34	export const LAENDER = [
35	  { id: "de", label: "Deutschland" },
36	  { id: "at", label: "Österreich" },
37	  { id: "ch", label: "Schweiz" },
38	];
39	
40	export const STANDARD = {
41	  mwp: 10,
42	  anschlussQuote: 1,
43	  km: 2,
44	  ebene: "auto",
45	  kapazitaet: "unbekannt",
46	  speicherMw: 0,
47	  speicherNetzbezug: false,
48	  cluster: false,
49	  land: "de",
50	};
51	
52	/** Spannweite der Kostenschätzung (Tiefbau, Querungen, Genehmigungen, Materialpreise) */
53	export const SPANNE = { min: 0.8, max: 1.4 };
54	/** Anteil gemeinsam genutzter Kosten (Trasse, Umspannwerk), die bei Clusterung mit einem Nachbarprojekt entfallen – eigene Annahme */
55	export const CLUSTER_ANTEIL = 0.5;
56	
57	const ERTRAG_DE = Math.round(REGIONEN.filter((r) => r.land === "DE").reduce((s, r) => s + r.ertrag, 0) / REGIONEN.filter((r) => r.land === "DE").length);
58	
59	/** Energieverlust (Anteil) bei Anschlussleistung/Modulleistung – lineare Interpolation der Tabelle */
60	export function abregelVerlust(quote) {
61	  const t = N.abregelung;
62	  if (quote >= t[0][0]) return 0;
63	  for (let i = 1; i < t.length; i++) {
64	    const [q1, v1] = t[i - 1];
65	    const [q2, v2] = t[i];
66	    if (quote >= q2) return v1 + ((q1 - quote) / (q1 - q2)) * (v2 - v1);
67	  }
68	  return t[t.length - 1][1];
69	}
70	
71	export function ebeneFuer(anschlussMw) {
72	  return anschlussMw <= N.grenzeMsMw ? "msLeitung" : anschlussMw <= N.grenzeUwMw ? "uwMs" : "hs";
73	}
74	
75	/** Kosten (mittlerer Schätzwert) für eine gegebene Anschlussleistung */
76	export function kosten(e, anschlussMw, ebene) {
77	  const posten = [];
78	  const kabelSysteme = Math.max(1, Math.ceil(anschlussMw / N.msSystemMw - 1e-9));
79	  const kabelMs = e.km * 1000 * FREIFLAECHE.kabelProMeter * (1 + (kabelSysteme - 1) * N.zusatzSystemFaktor);
80	  const teil = e.cluster ? 1 - CLUSTER_ANTEIL : 1;
81	
82	  posten.push({ id: "station", label: "Übergabe- und Trafostationen im Park", eur: e.mwp * FREIFLAECHE.netzanschlussFixProMwp, geteilt: false });
83	  if (ebene === "msLeitung") {
84	    posten.push({ id: "einschleifen", label: "Einschleifen in die MS-Leitung", eur: N.einschleifen, geteilt: false });
85	    posten.push({ id: "kabel", label: `Kabeltrasse 20 kV (${kabelSysteme} ${kabelSysteme > 1 ? "Systeme" : "System"})`, eur: kabelMs * teil, geteilt: e.cluster });
86	  } else if (ebene === "uwMs") {
87	    posten.push({ id: "feld", label: `Schaltfeld${kabelSysteme > 1 ? "er" : ""} im Umspannwerk (${kabelSysteme})`, eur: N.uwFeld.mittel * kabelSysteme, geteilt: false });
88	    posten.push({ id: "kabel", label: `Kabeltrasse 20 kV (${kabelSysteme} ${kabelSysteme > 1 ? "Systeme" : "System"})`, eur: kabelMs * teil, geteilt: e.cluster });
89	  } else {
90	    posten.push({ id: "uw", label: "Eigenes Umspannwerk 110/20 kV", eur: (N.kundenUwFix + N.kundenUwProMva * anschlussMw) * teil, geteilt: e.cluster });
91	    posten.push({ id: "kabel", label: "Kabeltrasse 110 kV", eur: e.km * N.hsKabelProKm.mittel * teil, geteilt: e.cluster });
92	  }
93	  if (e.speicherMw > 0 && e.speicherNetzbezug) {
94	    const satz = ebene === "hs" ? SPEICHER.bkzProKw.hs : SPEICHER.bkzProKw.ms;
95	    posten.push({ id: "bkz", label: "Baukostenzuschuss für Netzbezug des Speichers", eur: e.speicherMw * 1000 * satz, geteilt: false });
96	  }
97	  const summe = posten.reduce((s, p) => s + p.eur, 0);
98	  return { posten, summe, kabelSysteme };
99	}
100	
101	export function rechneNetzanschluss(eingabe = {}) {
102	  const e = { ...STANDARD, ...eingabe };
103	  const anschlussMw = e.mwp * e.anschlussQuote;
104	  const vorschlag = ebeneFuer(anschlussMw);
105	  const ebene = e.ebene === "auto" ? vorschlag : e.ebene;
106	  const k = kosten(e, anschlussMw, ebene);
107	
108	  // Überbauung: Vergleich mit voller Anschlussleistung
109	  const voll = kosten(e, e.mwp, e.ebene === "auto" ? ebeneFuer(e.mwp) : ebene);
110	  const einsparung = Math.max(0, voll.summe - k.summe);
111	  const verlustRoh = abregelVerlust(e.anschlussQuote);
112	  const kappung = Math.max(0, e.mwp - anschlussMw);
113	  const speicherAuffang = kappung > 0 ? Math.min(1, e.speicherMw / kappung) * 0.8 : 0;
114	  const verlust = verlustRoh * (1 - speicherAuffang);
115	  const ertragKwh = e.mwp * 1000 * ERTRAG_DE;
116	  const verlustKwh = ertragKwh * verlust;
117	  const verlustEurJahr = (verlustKwh * ERLOESE.eegFreiflaecheCt) / 100;
118	  const bwFaktor20 = (1 - Math.pow(1.05, -20)) / 0.05; // Barwert 20 Jahre bei 5 %
119	  const verlustBarwert = verlustEurJahr * bwFaktor20;
120	
121	  // Zeitrahmen in Monaten ab vollständigem Netzanschlussbegehren
122	  const basis = { msLeitung: [9, 18], uwMs: [12, 30], hs: [24, 48] }[ebene];
123	  const plus = { frei: [0, 0], unbekannt: [0, 12], knapp: [24, 60] }[e.kapazitaet];
124	  const trasse = e.km > 5 ? [3, 9] : [0, 0];
125	  const monate = [basis[0] + plus[0] + trasse[0], basis[1] + plus[1] + trasse[1]];
126	
127	  const capexAnlage = e.mwp * 1000 * FREIFLAECHE.capexProKwp.mittel;
128	
129	  // Ampel: Kostenanteil an der Anlage und Kapazität
130	  const anteil = k.summe / capexAnlage;
131	  const ampel = e.kapazitaet === "knapp" || anteil > 0.3 ? "kritisch" : e.kapazitaet === "unbekannt" || anteil > 0.15 ? "pruefen" : "gut";
132	
133	  const risiken = [];
134	  if (e.kapazitaet === "knapp") risiken.push("Netzausbau durch den Netzbetreiber nötig – die Kosten trägt er (§ 17 EEG), die Zeit tragen Sie: oft mehrere Jahre bis zur Einspeisung.");
135	  if (e.kapazitaet === "unbekannt") risiken.push("Kapazität unbekannt: Die Netzverträglichkeitsprüfung kann einen weiter entfernten Verknüpfungspunkt ergeben – das ändert Kosten und Zeitplan erheblich.");
136	  if (e.km > 5) risiken.push(`Lange Trasse (${e.km.toLocaleString("de-DE")} km): Jedes Flurstück braucht eine Leitungsdienstbarkeit; Querungen von Straßen, Bahn und Gewässern verlängern Planung und Genehmigung.`);
137	  if (ebene === "hs") risiken.push("110-kV-Anschluss: eigenes Umspannwerk mit langen Lieferzeiten für Transformatoren und eigenem Genehmigungsverfahren.");
138	  if (anteil > 0.15) risiken.push(`Der Netzanschluss macht rund ${Math.round(anteil * 100)} % der Anlagenkosten aus – das drückt die Rendite spürbar.`);
139	  if (e.speicherMw > 0 && e.speicherNetzbezug) risiken.push("Speicher mit Netzbezug: Baukostenzuschuss (BGH, 15.07.2025) und Bezugsnetzentgelte einplanen; Befreiungen nach aktuellem Stand befristet.");
140	  if (e.anschlussQuote < 0.7 && e.speicherMw === 0) risiken.push("Starke Überbauung ohne Speicher: spürbare Abregelungsverluste – ein Speicher kann sie großteils auffangen.");
141	  if (risiken.length === 0) risiken.push("Keine auffälligen Risiken aus den Angaben – entscheidend ist die verbindliche Auskunft des Netzbetreibers.");
142	
143	  const tipps = [];
144	  if (e.land === "de") {
145	    tipps.push(`Netzanschlussbegehren früh und vollständig nach § 8 EEG stellen: Der Netzbetreiber muss unverzüglich einen Zeitplan nennen und spätestens nach ${N.pruefWochen} Wochen das Ergebnis der Netzverträglichkeitsprüfung samt Kostenvoranschlag vorlegen (§ 8 Abs. 5 und 6 EEG).`);
146	    tipps.push("Reservierung klären: Viele Netzbetreiber reservieren Kapazität nur befristet und verlangen Nachweise zum Projektfortschritt (etwa Flächensicherung, Aufstellungsbeschluss) – teils mit Reservierungsentgelt. Die Regeln unterscheiden sich je Netzbetreiber.");
147	  }
148	  if (e.land === "at") tipps.push("Österreich: Netzzugang beim Verteilnetzbetreiber beantragen; es fallen Netzzutritts- und ggf. Netzbereitstellungsentgelte an. Kapazitäten werden je Netzbereich veröffentlicht – früh prüfen.");
149	  if (e.land === "ch") tipps.push("Schweiz: Anschlussbedingungen des Verteilnetzbetreibers maßgeblich; notwendige Netzverstärkungen werden in der Regel über die Netzkosten (Swissgrid) getragen – vorab bestätigen lassen.");
150	  if (!e.cluster) tipps.push("Clusterung prüfen: Mit Nachbarprojekten eine gemeinsame Trasse oder ein gemeinsames Umspannwerk nutzen – das teilt Kosten und Planungsaufwand.");
151	  else tipps.push("Clusterung: Kostenaufteilung, Bauabfolge und Haftung bei Verzögerung eines Partners vertraglich regeln.");
152	  if (e.anschlussQuote >= 0.95) tipps.push("Überbauung erwägen: Mit 70–80 % Anschlussleistung je MWp gehen oft nur wenige Prozent Ertrag verloren; eine flexible Netzanschlussvereinbarung nach § 8a EEG kann Kapazität schneller verfügbar machen.");
153	  if (e.speicherMw === 0) tipps.push("Speicher am selben Anschluss (Co-Location) glättet die Einspeisespitze, fängt Abregelung auf und schafft zusätzliche Erlöse.");
154	  tipps.push("Leitungsrechte früh sichern: Dienstbarkeiten entlang der Trasse sind oft der längste Weg – parallel zum B-Plan-Verfahren beginnen.");
155	
156	  return {
157	    eingabe: e,
158	    /** Länder-Sperre AT/CH: Kosten, BKZ und EEG-Verlustbewertung folgen deutschem Recht (markt.js LAENDER_SPERRE) */
159	    sperre: laenderSperre(e.land),
160	    anschlussMw,
161	    ebene,
162	    vorschlag,
163	    posten: k.posten,
164	    kabelSysteme: k.kabelSysteme,
165	    summe: k.summe,
166	    spanne: { min: k.summe * SPANNE.min, max: k.summe * SPANNE.max },
167	    proKwp: k.summe / (e.mwp * 1000),
168	    anteil,
169	    ampel,
170	    ueberbauung: { einsparung, verlust, verlustKwh, verlustEurJahr, verlustBarwert, lohnt: einsparung > verlustBarwert, speicherAuffang },
171	    monate,
172	    risiken,
173	    tipps,
174	  };
175	}
176	
177	/* ------------------------------------------------------------------ */
178	/* Selbsttest: node src/lib/rechner/netzanschluss.js                   */
179	/* ------------------------------------------------------------------ */
180	
181	export function selbsttest() {
182	  const fehler = [];
183	  const pruefe = (ok, t) => ok || fehler.push(t);
184	
185	  pruefe(abregelVerlust(1) === 0 && Math.abs(abregelVerlust(0.7) - 0.04) < 1e-9, "Abregelungstabelle exakt an Stützstellen");
186	  pruefe(Math.abs(abregelVerlust(0.75) - 0.0275) < 1e-9, "Interpolation zwischen 0,8 und 0,7");
187	  pruefe(ebeneFuer(8) === "msLeitung" && ebeneFuer(25) === "uwMs" && ebeneFuer(60) === "hs", "Ebenenvorschlag nach Leistung");
188	
189	  const r = rechneNetzanschluss({ mwp: 10, km: 2, anschlussQuote: 1, kapazitaet: "frei" });
190	  const kabel = 2000 * FREIFLAECHE.kabelProMeter;
191	  pruefe(r.ebene === "msLeitung", "10 MW → MS-Leitung");
192	  pruefe(Math.abs(r.summe - (10 * FREIFLAECHE.netzanschlussFixProMwp + N.einschleifen + kabel)) < 1, "Kostensumme MS = Stationen + Einschleifen + Kabel");
193	  pruefe(r.monate[0] === 9 && r.monate[1] === 18, "Zeitrahmen MS frei 9–18 Monate");
194	
195	  const gross = rechneNetzanschluss({ mwp: 30, km: 3 });
196	  pruefe(gross.ebene === "uwMs" && gross.kabelSysteme === 3, "30 MW → Umspannwerk, 3 Kabelsysteme");
197	  const ueber = rechneNetzanschluss({ mwp: 30, km: 3, anschlussQuote: 0.7 });
198	  pruefe(ueber.kabelSysteme === 2 && ueber.summe < gross.summe, "Überbauung spart ein Kabelsystem");
199	  pruefe(ueber.ueberbauung.einsparung > 0 && ueber.ueberbauung.verlust > 0, "Überbauung: Einsparung und Verlust ausgewiesen");
200	  const mitSp = rechneNetzanschluss({ mwp: 30, km: 3, anschlussQuote: 0.7, speicherMw: 9 });
201	  pruefe(mitSp.ueberbauung.verlust < ueber.ueberbauung.verlust, "Speicher fängt Abregelung auf");
202	  const hs = rechneNetzanschluss({ mwp: 80, km: 4 });
203	  pruefe(hs.ebene === "hs" && hs.summe > 5e6, "80 MW → 110 kV mit mehreren Mio. €");
204	  const cl = rechneNetzanschluss({ mwp: 80, km: 4, cluster: true });
205	  pruefe(cl.summe < hs.summe, "Clusterung senkt die Kosten");
206	  const bkz = rechneNetzanschluss({ mwp: 10, speicherMw: 5, speicherNetzbezug: true });
207	  pruefe(bkz.posten.some((p) => p.id === "bkz"), "Speicher mit Netzbezug → Baukostenzuschuss");
208	  pruefe(rechneNetzanschluss({ kapazitaet: "knapp" }).ampel === "kritisch", "knappe Kapazität → kritisch");
209	  pruefe(Math.abs(r.spanne.max / r.summe - SPANNE.max) < 1e-9, "Spanne konsistent");
210	  return { fehler, beispiel: r };
211	}
212	
213	if (typeof process !== "undefined" && process.argv?.[1] && /netzanschluss\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
214	  const { fehler } = selbsttest();
215	  for (const [mwp, km, q] of [[5, 1, 1], [10, 2, 1], [30, 3, 0.8], [80, 6, 0.8]]) {
216	    const r = rechneNetzanschluss({ mwp, km, anschlussQuote: q });
217	    console.log(`${mwp} MWp, ${km} km, ${q * 100} %: ${r.ebene}, ${Math.round(r.summe / 1000)} T€ (${Math.round(r.proKwp)} €/kWp, ${Math.round(r.anteil * 100)} % der Anlage), ${r.monate.join("–")} Monate`);
218	  }
219	  if (fehler.length) {
220	    console.error("FEHLER:\n- " + fehler.join("\n- "));
221	    process.exit(1);
222	  }
223	  console.log("Selbsttest netzanschluss.js: alle Prüfungen bestanden.");
224	}
