416	export function landPruefen(land) {
417	  const l = typeof land === "string" ? land.trim().toUpperCase() : "";
418	  if (!LAENDER.includes(l)) throw new PlattformFehler(422, "Bitte ein Land angeben (DE, AT oder CH).", "land");
