422	/** Stabile JSON-Darstellung (sortierte Schlüssel) – Grundlage der Prüf-ID */
423	export function stabil(x) {
424	  if (Array.isArray(x)) return `[${x.map(stabil).join(",")}]`;
425	  if (x && typeof x === "object") return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${stabil(x[k])}`).join(",")}}`;
426	  return JSON.stringify(x);
427	}
