429	/** Prüf-ID: 16 Hex-Zeichen in Vierergruppen, z. B. „3F2A-91C0-…“ */
430	export function pruefIdFuer({ rechner, land, eingaben, stand = STAND_RECHENLOGIK }) {
431	  const h = createHash("sha256").update(stabil({ rechner, land, eingaben, stand }), "utf8").digest("hex").slice(0, 16).toUpperCase();
432	  return h.match(/.{4}/g).join("-");
433	}
