435	/**
436	 * Neuberechnung auf dem Server.
437	 * @returns {{ rechner, titel, land, eingaben, roh, ergebnis, pruefId, stand, vorgangTyp }}
438	 *   roh: vollständiges Rechnerergebnis (nur für Tests/Vorgang, wird nicht gespeichert)
439	 *   ergebnis: Zusammenfassung für die Berichtsseite (Kennzahlen, Rechenweg, Tabellen, Hinweise)
440	 */
441	export function neuRechnen({ rechner, eingaben, land }) {
442	  const def = rechnerVon(rechner);
443	  const l = landPruefen(land);
444	  const e = eingabenPruefen(def.regeln, eingaben);
445	  def.landPruefen(e, l);
446	  const eingabenNorm = rechner === "flaechencheck" ? { ...e, land: l } : def.normalisieren ? def.normalisieren(e, l) : def.ohneRegion ? { ...e } : { ...e, regionId: e.regionId ?? standardRegion(l) };
447	  if (def.geldwerte && laenderSperre(l)) throw new PlattformFehler(422, `Für ${LAND_NAME[l]} ist dieser Bericht noch nicht verfügbar – die Rechenlogik wird gerade fachlich geprüft.`, "land_gesperrt");
448	  const roh = def.rechne(eingabenNorm, l);
449	  const zusammenfassung = def.zusammenfassen(roh, eingabenNorm, l);
450	  return {
451	    rechner,
452	    titel: def.titel,
453	    land: l,
454	    eingaben: eingabenNorm,
455	    roh,
456	    ergebnis: { ...zusammenfassung, sperre: roh.sperre ? { titel: roh.sperre.titel, text: roh.sperre.text } : null },
457	    pruefId: pruefIdFuer({ rechner, land: l, eingaben: eingabenNorm }),
458	    stand: STAND_RECHENLOGIK,
459	    vorgangTyp: def.vorgangTyp,
460	  };
461	}
