        ? [kz("Gesetzliche Fristen", "§ 8 Abs. 5 und 6 EEG", r.schritte.find((s) => s.frist && s.id === "de-pruefung")?.frist.de || "")]
        : [kz("Fristen", "beim Netzbetreiber erfragen", "kein geprüfter Wert – siehe Hinweis")]),
